---@meta
-- The Rivet 0.1.0 Lua API, for Lua language servers (LuaLS; listed as the library of
-- this project's .luarc.json). Generated by the editor from the engine's registries: do not edit,
-- File > Create Lua Helpers writes it again.

-- ---- Scripts ------------------------------------------------------------------------------------

---The table a Lua script returns; attach the script to an entity with a LuaScript component. Every
---entity running the script gets its own instance, `self`, which falls back to this table for its
---methods. Declare the script's class to get completion on `self`:
---
---```lua
------@class Player : RivetScript
------@field speed number
---local Player = { properties = { speed = 2.0 } }
---
---function Player:onUpdate(dt)
---    self.entity.position = self.entity.position + Vec3(self.speed * dt, 0, 0)
---end
---
---return Player
---```
---
---Messages (`entity:send("hit", 5)`, Script.send, Script.broadcast) call the method of that name:
---`function Player:hit(damage)`.
---@class RivetScript
---@field entity Entity The entity running this instance of the script.
---@field properties? table<string, any> Per-instance properties and their defaults, edited in the inspector; each is copied into `self`.
---@field [string] any Properties, and anything else the script stores on `self`.
local RivetScript = {}

---Called once, before the instance's first update.
function RivetScript:onStart() end

---Called every frame.
---@param dt number Seconds since the last frame, scaled by the time scale.
function RivetScript:onUpdate(dt) end

---Called every physics step.
---@param dt number Seconds per step (the project's fixed timestep).
function RivetScript:onFixedUpdate(dt) end

---Called every frame, after every script's onUpdate.
---@param dt number Seconds since the last frame, scaled by the time scale.
function RivetScript:onLateUpdate(dt) end

---Called when the entity is destroyed or play stops.
function RivetScript:onDestroy() end

---A 2D body of this entity started touching another.
---@param other Entity
function RivetScript:onCollisionEnter2D(other) end

---A 2D body of this entity stopped touching another.
---@param other Entity
function RivetScript:onCollisionExit2D(other) end

---Another 2D body entered this entity's trigger, or this entity entered one.
---@param other Entity
function RivetScript:onTriggerEnter2D(other) end

---A 2D body left this entity's trigger, or this entity left one.
---@param other Entity
function RivetScript:onTriggerExit2D(other) end

---A 3D body of this entity started touching another.
---@param other Entity
function RivetScript:onCollisionEnter3D(other) end

---A 3D body of this entity stopped touching another.
---@param other Entity
function RivetScript:onCollisionExit3D(other) end

---Another 3D body entered this entity's trigger, or this entity entered one.
---@param other Entity
function RivetScript:onTriggerEnter3D(other) end

---A 3D body left this entity's trigger, or this entity left one.
---@param other Entity
function RivetScript:onTriggerExit3D(other) end

