-- ---- Standard library ---------------------------------------------------------------------------

---The script sandbox keeps only the time functions of os (no files, processes or environment).
os = {}

---Formats a date (C strftime format); "*t" and "!*t" return the fields as a table instead.
---@param format? string
---@param time? integer
---@return string|table
function os.date(format, time) end

---The current time in seconds since the epoch, or the time of a date table.
---@param date? table
---@return integer
function os.time(date) end

---Processor time used so far, in seconds.
---@return number
function os.clock() end

---Seconds from t1 to t2.
---@param t2 integer
---@param t1 integer
---@return number
function os.difftime(t2, t1) end

-- ---- Entities and components -------------------------------------------------------------

---An entity of the running scene; `self.entity` is the one running a script. Every Entity.*
---function also works as a method: `Entity.getName(e)` is `e:getName()`.
---@class Entity
---@field name string
---@field tag string
---@field active boolean The entity's own active flag; it only runs if its parents are active too.
---@field position Vec3 Position relative to the parent.
---@field rotation Quat Rotation relative to the parent.
---@field scale Vec3 Scale relative to the parent.
---@field worldPosition Vec3 Position in world space.
---@field parent Entity? The parent, or nil for a root; assigning keeps the world transform.
---@field transform TransformComponent
Entity = {}

---The first descendant (at any depth) with the name, or nil.
---@param name string
---@return Entity?
function Entity:findChild(name) end

---@param name ComponentName
---@return boolean
function Entity:hasComponent(name) end

---Removes a component (Transform and EntityInfo cannot be removed).
---@param name ComponentName
function Entity:removeComponent(name) end

---Calls the method named message on the entity's scripts, with the argument.
---@param message string
---@param argument? any
function Entity:send(message, argument) end

---A property of the entity's script, or nil.
---@param property string
---@return any
function Entity:get(property) end

---Sets a property of the entity's script; false if the entity runs no script.
---@param property string
---@param value any
---@return boolean
function Entity:set(property, value) end

---The named component, or nil if the entity has none.
---@param name ComponentName
---@return AnyComponent?
---@overload fun(self: Entity, name: "EntityInfo"): EntityInfoComponent?
---@overload fun(self: Entity, name: "Transform"): TransformComponent?
---@overload fun(self: Entity, name: "Camera"): CameraComponent?
---@overload fun(self: Entity, name: "Light"): LightComponent?
---@overload fun(self: Entity, name: "MeshRenderer"): MeshRendererComponent?
---@overload fun(self: Entity, name: "SpriteRenderer"): SpriteRendererComponent?
---@overload fun(self: Entity, name: "TextRenderer"): TextRendererComponent?
---@overload fun(self: Entity, name: "Environment"): EnvironmentComponent?
---@overload fun(self: Entity, name: "RigidBody2D"): RigidBody2DComponent?
---@overload fun(self: Entity, name: "Collider2D"): Collider2DComponent?
---@overload fun(self: Entity, name: "RigidBody3D"): RigidBody3DComponent?
---@overload fun(self: Entity, name: "Collider3D"): Collider3DComponent?
---@overload fun(self: Entity, name: "LuaScript"): LuaScriptComponent?
---@overload fun(self: Entity, name: "VisualScript"): VisualScriptComponent?
---@overload fun(self: Entity, name: "NativeScript"): NativeScriptComponent?
---@overload fun(self: Entity, name: "AudioSource"): AudioSourceComponent?
function Entity:getComponent(name) end

---Adds the component if the entity has none, sets the given fields and returns it.
---@param name ComponentName
---@param values? table<string, any> Field values, e.g. `{ intensity = 2 }`.
---@return AnyComponent
---@overload fun(self: Entity, name: "EntityInfo", values?: table<string, any>): EntityInfoComponent
---@overload fun(self: Entity, name: "Transform", values?: table<string, any>): TransformComponent
---@overload fun(self: Entity, name: "Camera", values?: table<string, any>): CameraComponent
---@overload fun(self: Entity, name: "Light", values?: table<string, any>): LightComponent
---@overload fun(self: Entity, name: "MeshRenderer", values?: table<string, any>): MeshRendererComponent
---@overload fun(self: Entity, name: "SpriteRenderer", values?: table<string, any>): SpriteRendererComponent
---@overload fun(self: Entity, name: "TextRenderer", values?: table<string, any>): TextRendererComponent
---@overload fun(self: Entity, name: "Environment", values?: table<string, any>): EnvironmentComponent
---@overload fun(self: Entity, name: "RigidBody2D", values?: table<string, any>): RigidBody2DComponent
---@overload fun(self: Entity, name: "Collider2D", values?: table<string, any>): Collider2DComponent
---@overload fun(self: Entity, name: "RigidBody3D", values?: table<string, any>): RigidBody3DComponent
---@overload fun(self: Entity, name: "Collider3D", values?: table<string, any>): Collider3DComponent
---@overload fun(self: Entity, name: "LuaScript", values?: table<string, any>): LuaScriptComponent
---@overload fun(self: Entity, name: "VisualScript", values?: table<string, any>): VisualScriptComponent
---@overload fun(self: Entity, name: "NativeScript", values?: table<string, any>): NativeScriptComponent
---@overload fun(self: Entity, name: "AudioSource", values?: table<string, any>): AudioSourceComponent
function Entity:addComponent(name, values) end

---The name of a registered component.
---@alias ComponentName
---| "EntityInfo"
---| "Transform"
---| "Camera"
---| "Light"
---| "MeshRenderer"
---| "SpriteRenderer"
---| "TextRenderer"
---| "Environment"
---| "RigidBody2D"
---| "Collider2D"
---| "RigidBody3D"
---| "Collider3D"
---| "LuaScript"
---| "VisualScript"
---| "NativeScript"
---| "AudioSource"
