-- ---- Test --------------------------------------------------------------------------------------

Test = {}

---Records a test check; logs and counts a failure if the condition is false.
---@param condition? boolean Default: false.
---@param message? string Default: "".
---@return boolean passed
function Test.check(condition, message) end

---Checks that two values are equal.
---@param actual? any
---@param expected? any
---@param message? string Default: "".
---@return boolean passed
function Test.equal(actual, expected, message) end

---Checks that two numbers are within a tolerance.
---@param actual? number Default: 0.
---@param expected? number Default: 0.
---@param tolerance? number Default: 0.001.
---@param message? string Default: "".
---@return boolean passed
function Test.near(actual, expected, tolerance, message) end

---Records a named passing step.
---@param name? string Default: "".
function Test.pass(name) end

---Records a failure.
---@param message? string Default: "".
function Test.fail(message) end

---Announces errors the test logs on purpose, so they do not fail the run.
---@param count? integer Default: 1.
function Test.expectErrors(count) end

---Marks the test run as complete (the runtime's --test mode then exits).
function Test.finish() end

---True once Test.finish was called.
---@return boolean finished
function Test.isFinished() end
